<!-- This file is generated by AI. -->

<!--
  语句配音历史 (配音卡操作台右侧)。

  **历史是按"当前这一句对话"组织的**, 不是整个场景共用一份: 换一句对话就该换一批记录,
  否则左右两边说的不是同一件事。

  每条记录对应一次「测试」或「生成」; 排队中 / 生成中的任务可以取消, 排队中的还能改
  优先级。参数编辑不影响既有记录。条目右键菜单的项见脚本里的 `menuItems`。

  ⚠️ **响应性来源**: 卡片的 `history` 是控制器里的普通数组, 就地改它不触发任何重算。
  控制器每次同步都会把**一份新的 Map** (内含新的卡片对象) 写进 `appStore.sceneVoiceEditors`,
  所以这里读 store 那一份才有响应性 —— 读 `voiceController.getCard()` 会拿到旧引用。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { save } from '@tauri-apps/plugin-dialog';
  import { revealItemInDir } from '@tauri-apps/plugin-opener';

  import { fs } from '../lib/fs';
  import { appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { errorSummary } from '../voice/errorText';
  import { formatDuration } from '../voice/estimate';
  import type { HistoryEntry } from '../voice/types';
  import Button from './Button.svelte';
  import ContextMenu, { type ContextMenuItem } from './ContextMenu.svelte';
  import Icon from './Icon.svelte';
  import PriorityButton from './PriorityButton.svelte';
  import TakePlayer from './TakePlayer.svelte';
  import TaskProgress from './TaskProgress.svelte';
  import VoiceErrorDialog from './VoiceErrorDialog.svelte';

  let {
    cardId,
    /** 当前对话行 (0 基) */
    line,
  }: {
    cardId: string;
    line: number;
  } = $props();

  /** 即时反馈 (已应用 / 已导出 / 失败原因…) */
  let message = $state<string | null>(null);
  /** 正在查看详情的失败记录 (null = 对话框未打开) */
  let errorEntry = $state<HistoryEntry | null>(null);
  /** 条目右键菜单 */
  let menu = $state<{ x: number; y: number; entry: HistoryEntry } | null>(null);

  /** 本卡: 从 store 读, 而不是 `voiceController.getCard()`。 */
  const card = $derived(appStore.sceneVoiceEditors.get(cardId) ?? null);

  /*
   * ⚠️ **下面这几个派生都要读一次 `appStore.voiceTick`, 而且必须让自己产出新值。**
   *
   * 控制器是在**原地**改卡片的 (换 `card.history` 数组、直接改 `entry.status` 等字段), 而入队后的
   * `emit()` 只自增令牌、**不换 `card` 对象**。`$derived` 用 `===` 比较新旧值, 值没变就不往下游传播,
   * 于是"只在中间层 (`card`) 上读令牌"会被吞掉, 下游一直拿到缓存里的旧数组 (表现: 点生成后本句历史
   * 不出现任务卡, 切走再切回来才看得到)。`filter` / `find` 每次都产出新值, 只要重算就一定往下传。
   *
   * ⚠️ **每一项还要浅拷贝一层。** 新数组只解决"成员出现/消失": `{#each ... (entry.id)}` 对**键相同**
   * 的项复用那一行, 且按 `===` 判断项的新值 —— 传**同一个对象引用**就不传播, 行模板不会重跑, 任务
   * 在跑时就地改的字段 (`status` / `startedAt` / 完成态) 会停在建项那一刻 (有预估时间却没有进度条)。
   * 浅拷贝让每项的引用随令牌变化, 行模板才会重跑。
   */
  const entries = $derived.by<HistoryEntry[]>(() => {
    void appStore.voiceTick;
    return (card?.history ?? []).filter((entry) => entry.line === line).map((entry) => ({ ...entry }));
  });
  const selectedId = $derived.by(() => {
    void appStore.voiceTick;
    return card?.selectedHistoryId ?? null;
  });

  /** 计数: 已生成 / 进行中 / 未完成 */
  const doneCount = $derived(entries.filter((entry) => entry.status === 'done').length);
  const activeCount = $derived(
    entries.filter((entry) => entry.status === 'pending' || entry.status === 'running').length
  );
  const failedCount = $derived(entries.filter((entry) => entry.status === 'failed').length);
  /** 未能对齐到任何语句的残留记录 (被上面的过滤排除, 需要一个清理入口) */
  const unaligned = $derived.by(() => {
    void appStore.voiceTick;
    return (card?.history ?? []).filter((entry) => entry.line === null).length;
  });
  /**
   * 本句已应用的那一条音频哈希前缀 (底部给出说明)。
   *
   * 取**字符串**而不是那一条记录: 返回对象的话, `applied` 在原对象上就地翻转时新值仍是同一个
   * 引用, 派生不传播。
   */
  const appliedHash = $derived.by(() => {
    void appStore.voiceTick;
    const entry = (card?.history ?? []).find((item) => item.line === line && item.applied);
    return entry?.audioHash?.slice(0, 8) ?? null;
  });
  const hasTestEntries = $derived(entries.some((entry) => entry.kind === 'test'));

  function togglePriority(entry: HistoryEntry): void {
    voiceController.setPriority(entry.id, entry.priority === 'immediate' ? 'normal' : 'immediate');
  }

  /** 应用到脚本: 控制器负责改文件与重新解析。 */
  async function apply(entry: HistoryEntry): Promise<void> {
    try {
      await voiceController.apply(cardId, entry.id);
      message = '已应用并写入 -vocal=';
    } catch (error) {
      message = errorSummary(String(error));
    }
  }

  /** 把一条失败记录原样重排队。 */
  function retry(entry: HistoryEntry): void {
    const task = voiceController.retryFromHistory(cardId, entry.id);
    message = task ? '已按该参数重新入队' : '该记录已无法对齐到语句，无法重试';
  }

  function drop(entry: HistoryEntry): void {
    voiceController.dropHistory(cardId, entry.id);
  }

  function cancel(entry: HistoryEntry): void {
    voiceController.cancel(entry.id);
  }

  /** 在文件管理器中显示这一条生成的音频。 */
  async function reveal(entry: HistoryEntry): Promise<void> {
    if (!entry.audioPath) return;
    try {
      await revealItemInDir(entry.audioPath);
    } catch (error) {
      message = errorSummary(String(error));
    }
  }

  /** 导出音频: 让用户选目标文件, 再把 wav 复制过去。 */
  async function exportAudio(entry: HistoryEntry): Promise<void> {
    if (!entry.audioPath) return;
    const destination = await save({
      defaultPath: `${entry.characterName || 'voice'}-${entry.audioHash?.slice(0, 8) ?? 'audio'}.wav`,
      filters: [{ name: 'WAV 音频', extensions: ['wav'] }],
    });
    if (typeof destination !== 'string') return;
    try {
      await fs.copyFile(entry.audioPath, destination);
      message = '已导出音频';
    } catch (error) {
      message = errorSummary(String(error));
    }
  }

  /**
   * 复制种子。
   *
   * 种子是"复现这一次结果"的唯一凭据: 参数面板上那一栏可以被改动, 记录里的这一份不会,
   * 所以要从记录里取。负数 (服务端随机) 没有复制价值, 菜单项直接禁用。
   */
  async function copySeed(seed: number): Promise<void> {
    try {
      await navigator.clipboard.writeText(String(seed));
      message = `已复制种子 ${seed}`;
    } catch (error) {
      message = `复制失败：${errorSummary(String(error))}`;
    }
  }

  // ---- 条目右键菜单: 项、顺序、分隔线、禁用条件; 行内按钮保留 (两者不冲突) ----
  const menuItems = $derived.by<ContextMenuItem[]>(() => {
    const entry = menu?.entry;
    if (!entry) return [];
    const inFlight = entry.status === 'pending' || entry.status === 'running';
    const items: ContextMenuItem[] = [
      {
        key: 'apply',
        label: '应用',
        iconName: 'Checkmark',
        disabled: entry.status !== 'done' || entry.applied || entry.line === null,
        onClick: () => void apply(entry),
      },
      {
        key: 'reveal',
        label: '在文件夹中显示',
        iconName: 'FolderOpen',
        disabled: !entry.audioPath,
        onClick: () => void reveal(entry),
      },
      {
        key: 'export',
        label: '导出音频',
        iconName: 'ArrowDownload',
        disabled: !entry.audioPath,
        onClick: () => void exportAudio(entry),
      },
      {
        key: 'copySeed',
        label: '复制种子',
        iconName: 'Copy',
        disabled: entry.params.seed < 0,
        onClick: () => void copySeed(entry.params.seed),
      },
      {
        key: 'retry',
        label: '以此参数重试',
        iconName: 'ArrowSync',
        title: '用这一条记录的参数重新入队（不改动原记录）',
        disabled: entry.line === null,
        onClick: () => retry(entry),
      },
    ];
    // 排队中/进行中才有下面这一组 (未完成时"隐藏"而不是"禁用" —— 禁用项读起来像功能坏了)
    if (inFlight) items.push({ key: 'separator-queue', separator: true });
    if (entry.status === 'pending') {
      items.push({
        key: 'priority',
        label: entry.priority === 'immediate' ? '降为常规' : '改为优先',
        iconName: entry.priority === 'immediate' ? 'ArrowDown' : 'ArrowUp',
        title: `当前：${entry.priority === 'immediate' ? '优先' : '常规'}队列`,
        onClick: () => togglePriority(entry),
      });
    }
    if (inFlight) {
      items.push({
        key: 'cancel',
        label: '取消',
        iconName: 'Dismiss',
        onClick: () => cancel(entry),
      });
    }
    items.push(
      { key: 'separator-destructive', separator: true },
      { key: 'drop', label: '删除', iconName: 'Delete', danger: true, onClick: () => drop(entry) },
      {
        key: 'dropTests',
        label: '删除本句全部测试',
        iconName: 'FilterDismiss',
        danger: true,
        onClick: () => voiceController.dropHistoryByLine(cardId, line, 'test'),
      },
      {
        key: 'dropAll',
        label: '删除本句全部',
        iconName: 'Broom',
        danger: true,
        onClick: () => voiceController.dropHistoryByLine(cardId, line),
      }
    );
    return items;
  });

  /** 记录时间: 卡片窄栏放不下年份, 用「月-日 时:分」 */
  function formatTime(timestamp: number): string {
    const date = new Date(timestamp);
    const pad = (value: number) => String(value).padStart(2, '0');
    return `${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
  }
</script>

<div class="voice-history">
  <div class="history-toolbar">
    <span class="history-title">历史</span>
    <span class="history-count">
      {doneCount} 已生成{#if activeCount > 0}
        · {activeCount} 进行中{/if}{#if failedCount > 0}
        · {failedCount} 未完成{/if}
    </span>
    <span class="voice-actions-spacer"></span>
    <!-- 批量清理只留图标 (与工作台队列一致, 文案放悬浮提示); 只作用于**当前这一句** -->
    <Button
      appearance="bare"
      icon="FilterDismiss"
      title="删除本句的全部测试记录"
      disabled={!hasTestEntries}
      onclick={() => voiceController.dropHistoryByLine(cardId, line, 'test')}
    />
    <Button
      appearance="bare"
      icon="Broom"
      title="删除本句的全部记录（不影响已应用的 -vocal=）"
      disabled={entries.length === 0}
      onclick={() => voiceController.dropHistoryByLine(cardId, line)}
    />
  </div>

  <div class="history-list">
    {#if entries.length === 0}
      <p class="history-empty">本句还没有记录。点击「测试」快速试听，或直接「生成」。</p>
    {/if}

    {#each entries as entry (entry.id)}
      {@const inFlight = entry.status === 'pending' || entry.status === 'running'}
      <div
        class="history-item"
        class:selected={entry.id === selectedId}
        class:failed={entry.status === 'failed'}
        role="button"
        tabindex="0"
        onclick={() => voiceController.selectHistory(cardId, entry.id)}
        onkeydown={(event) => {
          if (event.key === 'Enter' || event.key === ' ') voiceController.selectHistory(cardId, entry.id);
        }}
        oncontextmenu={(event) => {
          // 右键只开菜单, 不改选中: 选中有自己的左键语义
          event.preventDefault();
          menu = { x: event.clientX, y: event.clientY, entry };
        }}
      >
        <!-- 基本信息与操作图标同一行 -->
        <div class="history-head">
          <span class="history-kind {entry.kind}">
            {entry.kind === 'test' ? '测试' : '生成'} x{entry.params.sampleSteps}
          </span>
          <span class="history-time">{formatTime(entry.createdAt)}</span>
          {#if entry.applied}
            <span class="history-applied" title="已应用到脚本"><Icon name="CheckmarkCircle" size={12} /></span>
          {/if}

          <span class="history-head-actions">
            {#if inFlight}
              <!--
                生成中的项**不提供播放/删除**: 还没有音频可放, 也不该在跑的时候把记录
                删掉。留下的两件事是"改优先级"(仅排队中) 与"取消"。
              -->
              {#if entry.status === 'pending'}
                <PriorityButton priority={entry.priority} onToggle={() => togglePriority(entry)} />
              {/if}
              <Button
                appearance="bare"
                icon="Dismiss"
                title={entry.status === 'running'
                  ? '取消（推理无法中断，返回后丢弃结果）'
                  : '取消（还没开始，直接撤下）'}
                onclick={(event) => {
                  event.stopPropagation();
                  cancel(entry);
                }}
              />
            {:else}
              {#if entry.status === 'done' && entry.audioPath}
                <TakePlayer path={entry.audioPath} key={entry.id} />
              {/if}
              <Button
                appearance="bare"
                icon="Delete"
                title="删除记录"
                onclick={(event) => {
                  event.stopPropagation();
                  drop(entry);
                }}
              />
            {/if}
          </span>
        </div>

        <div class="history-text">{entry.text || '（空）'}</div>

        <div class="history-meta">
          <span>{entry.characterName || '未指定角色'}</span>
          {#if entry.alignment === 'speakerChanged'}
            <span class="history-warn">归属可能已变</span>
          {/if}
          {#if entry.params.seed >= 0}
            <span>种子 {entry.params.seed}</span>
          {/if}
          <!-- `响应` = 这一次请求的实测往返时间 (任务耗时); 音频时长对配音没有参考价值, 不显示 -->
          {#if entry.elapsed !== undefined}
            <span>响应 {formatDuration(entry.elapsed)}</span>
          {/if}
        </div>

        {#if inFlight}
          <div class="history-progress">
            <TaskProgress
              steps={entry.params.sampleSteps}
              text={entry.text}
              startedAt={entry.status === 'running' ? entry.startedAt : undefined}
            />
          </div>
        {/if}

        {#if entry.error}
          <!--
            报错只留一行摘要 + 一个入口: GSOV 的原始报错有几十行, 铺在卡片里会把
            整栏撑爆。点这一行打开弹窗看全文 (可复制)。
          -->
          <button
            type="button"
            class="error-chip"
            title="查看完整报错"
            onclick={(event) => {
              event.stopPropagation();
              errorEntry = entry;
            }}
          >
            <span class="error-chip-icon"><Icon name="ErrorCircle" size={12} /></span>
            <span class="error-chip-text">{errorSummary(entry.error)}</span>
            <span class="error-chip-more">详情</span>
          </button>
        {/if}
      </div>
    {/each}
  </div>

  {#if unaligned > 0}
    <div class="history-unaligned">
      <span>{unaligned} 条记录未能对齐到任何语句</span>
      <Button
        appearance="bare"
        icon="Broom"
        title="删除这些无法对齐的残留记录"
        onclick={() => voiceController.dropUnalignedHistory(cardId)}
      />
    </div>
  {/if}

  {#if appliedHash}
    <div class="history-applied-note">当前语句已应用：{appliedHash}</div>
  {/if}
  {#if message}
    <div class="history-message">{message}</div>
  {/if}

  <!-- 条目右键菜单 (项见脚本里的 `menuItems`) -->
  {#if menu}
    <ContextMenu x={menu.x} y={menu.y} items={menuItems} onClose={() => (menu = null)} />
  {/if}
</div>

{#if errorEntry}
  <VoiceErrorDialog
    error={errorEntry.error ?? null}
    description={`${errorEntry.characterName || '未指定角色'} · ${
      errorEntry.kind === 'test' ? '测试' : '生成'
    } x${errorEntry.params.sampleSteps} · ${formatTime(errorEntry.createdAt)}`}
    onClose={() => (errorEntry = null)}
  />
{/if}
